mapper.update:
UPDATE exam_user_answer
SET grader_id=#{graderId}
WHERE no=#{answerNo}
  AND is_correct='W'
  AND grader_id IS NULL

UPDATE exam_user_answer
SET grader_id=NULL
WHERE no=#{answerNo}
  AND grader_id=#{graderId}
  AND is_correct='W'

mapper.select:
SELECT enrollment_no
FROM exam_user_answer
WHERE no=#{answerNo}
  AND grader_id=#{graderId}
  AND is_correct='W'

mapper.update:
UPDATE exam_enrollment
SET totalscore=(
        SELECT NVL(SUM(score), 0)
        FROM exam_user_answer
        WHERE enrollment_no=#{enrollmentNo}
    ),
    status='COMPLETE'
WHERE no=#{enrollmentNo}
